"""L4 -- build something that uses the detector.

One contract, three reasonable things to build with it. Pick one:

  blur       obscure every detected face; the privacy tool
  count      draw the boxes and stamp the count; the attendance counter
  overlay    draw something on each face; the AR toy

The grader does not care which you chose. It checks that a real image came
back, that it differs from the one that went in, that the differences are
concentrated in and around the face boxes rather than smeared over the whole
frame, and that the report carries the required keys. Those are true of all
three, which is the point -- the level grades whether your app works, not
whether the instructor liked your idea.

This is the open-ended level. Its output is the artifact you keep, and taste
is not graded.
"""

from __future__ import annotations

import numpy as np



def process(image, faces, mode="blur"):
    """Apply `mode` to every face in `image` and describe what happened.

    image  : an (H, W, 3) uint8 RGB array
    faces  : list of (x1, y1, x2, y2) integer boxes, as `detect_faces` returns
    mode   : "blur", "count" or "overlay"

    Returns (annotated, report) where:
      annotated : a NEW (H, W, 3) uint8 array. Do not modify `image` in place;
                  the grader compares the two.
      report    : a dict with at least these keys
                    "n_faces"      int, how many boxes were acted on
                    "mode"         str, the mode applied
                    "coverage"     float in [0, 1], the fraction of the frame
                                   area inside face boxes

    An image with no faces still returns a valid pair: a copy of the input and
    a report with n_faces 0.

    Boxes can run past the edge of the frame. Clip them before you index.
    """
# Pillow does the blur
    from PIL import Image, ImageFilter

# make sure it's a uint8 array
    image = np.asarray(image, dtype=np.uint8)

# height and width
    h, w = image.shape[:2]

# copy so the original isn't changed
    out = image.copy()

# marks pixels inside face boxes (for coverage)
    covered = np.zeros((h, w), dtype=bool)

# faces changed
    n = 0

    for box in faces:
# box corners as ints
        x1, y1, x2, y2 = (int(round(v)) for v in box)

# clip box to the image
        x1, x2 = max(0, min(x1, w)), max(0, min(x2, w))
        y1, y2 = max(0, min(y1, h)), max(0, min(y2, h))

# skip empty boxes
        if x2 <= x1 or y2 <= y1:
            continue

        n += 1
# mark face area
        covered[y1:y2, x1:x2] = True

        if mode == "blur":
# blur the face area and put it back
            patch = Image.fromarray(out[y1:y2, x1:x2])
# bigger face, stronger blur
            radius = max(4, (x2 - x1) // 6)
            out[y1:y2, x1:x2] = np.asarray(patch.filter(ImageFilter.GaussianBlur(radius)))
        else:
# other modes: draw a box outline
            t = max(2, (x2 - x1) // 60)
# orange for count, blue for overlay
            colour = np.array([255, 200, 0] if mode == "count" else [0, 220, 255], dtype=np.uint8)
# top
            out[y1:y1 + t, x1:x2] = colour
# bottom
            out[y2 - t:y2, x1:x2] = colour
# left
            out[y1:y2, x1:x1 + t] = colour
# right
            out[y1:y2, x2 - t:x2] = colour

# report: face count, mode, fraction of image that is face
    report = {"n_faces": int(n), "mode": str(mode),
              "coverage": float(covered.mean()) if h and w else 0.0}
    return out, report
